from unittest.mock import patch
from test_release import image, release
sys.path.insert(0, str(Path(__file__).parents[2]/'tools'))
import icon256_update_feed as feed


class FeedTests(unittest.TestCase):
    def test_ci_token_stays_on_repository_api_requests(self):
        requests = []
        def open_request(request, **kwargs):
            requests.append(request)
            return io.BytesIO(b'[]')
        with patch.dict(os.environ, {'GH_TOKEN': 'test-only-token'}), patch.object(urllib.request, 'urlopen', open_request):
            feed.fetch('https://api.github.com/repos/ThingPulse/WLED-Icon256/releases', 100)
            feed.fetch('https://github.com/ThingPulse/WLED-Icon256/releases/download/v1.0.0/manifest.json', 100)
        self.assertEqual(requests[0].get_header('Authorization'), 'Bearer test-only-token')
        self.assertIsNone(requests[1].get_header('Authorization'))
        redirected = urllib.request.HTTPRedirectHandler().redirect_request(requests[0], None, 302, 'Found', {}, 'https://release-assets.githubusercontent.com/asset')
        self.assertIsNone(redirected.get_header('Authorization'))

    def test_publication_integrity_and_immutable_feed(self):
        with tempfile.TemporaryDirectory() as tmp:
            root = Path(tmp)
            remote, checkout, artifacts = root/'remote.git', root/'checkout', root/'assets'
            def git(*args):
                return subprocess.check_output(['git', *map(str,args)], stderr=subprocess.DEVNULL, text=True).strip()
            git('init','--bare',remote);git('clone',remote,checkout)
            git('-C',checkout,'config','user.email','test@example.invalid')
            git('-C',checkout,'config','user.name','Test')
            (checkout/'README').write_text('Source stays on main')
            git('-C',checkout,'add','.');git('-C',checkout,'commit','-m','Initial');git('-C',checkout,'branch','-M','main');git('-C',checkout,'push','origin','main')
            binary = root/'firmware.bin';binary.write_bytes(image('1.2.3-beta.1'))
            manifest = release.package(binary,artifacts,'v1.2.3-beta.1','ThingPulse/WLED-Icon256','a'*40)
            names = ['manifest.json','SHA256SUMS',manifest['firmware']['filename']]
            record = {'draft':True,'published_at':None,'tag_name':manifest['tag'],'prerelease':True,'assets':[{'name':n,'browser_download_url':f'https://github.com/ThingPulse/WLED-Icon256/releases/download/{manifest["tag"]}/{n}'} for n in names]}
            def fetch(url,limit):
                if '/releases?' in url:return json.dumps([record]).encode()
                return (artifacts/url.rsplit('/',1)[-1]).read_bytes()
            with patch.object(feed,'fetch',fetch):
                feed.build_feed('ThingPulse/WLED-Icon256',checkout)
                self.assertEqual(json.loads((checkout/'catalog.json').read_text())['releases'],[])
                record.update(draft=False,published_at='2026-11-20T00:00:00Z')
                feed.build_feed('ThingPulse/WLED-Icon256',checkout)
                catalog=json.loads((checkout/'catalog.json').read_text());self.assertEqual(len(catalog['releases']),1)
                commit=catalog['releases'][0]['commit'];self.assertEqual(git('-C',checkout,'show',commit+':'+manifest['tag']+'/manifest.json'),(artifacts/'manifest.json').read_text().strip())
                feed.build_feed('ThingPulse/WLED-Icon256',checkout)
                self.assertEqual(json.loads((checkout/'catalog.json').read_text()),catalog)
                (artifacts/names[2]).write_bytes(b'corrupt')
                with self.assertRaises(ValueError):feed.build_feed('ThingPulse/WLED-Icon256',checkout)
                self.assertEqual(git('-C',checkout,'show','origin/main:README'),'Source stays on main')
